import "server-only";
import fs from "node:fs/promises";
import path from "node:path";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { env } from "@/lib/env";

/**
 * File storage port. `local` writes to .data/uploads and serves files via
 * /api/files/*. `s3` talks to AWS S3, or MinIO/R2 when S3_ENDPOINT is set.
 */
export interface Storage {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  url(key: string): string;
}

export const LOCAL_UPLOAD_DIR = path.join(process.cwd(), ".data", "uploads");

/** Keys are generated by us, but never let one escape the upload dir. */
export function safeLocalPath(key: string) {
  const full = path.resolve(LOCAL_UPLOAD_DIR, key);
  if (!full.startsWith(path.resolve(LOCAL_UPLOAD_DIR) + path.sep)) {
    throw new Error("Invalid storage key");
  }
  return full;
}

const localStorage: Storage = {
  async put(key, bytes) {
    const file = safeLocalPath(key);
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, bytes);
  },
  url: (key) => `/api/files/${key}`,
};

function s3Storage(): Storage {
  const e = env();
  const client = new S3Client({
    region: e.S3_REGION,
    endpoint: e.S3_ENDPOINT,
    forcePathStyle: Boolean(e.S3_ENDPOINT),
    credentials: { accessKeyId: e.S3_ACCESS_KEY_ID!, secretAccessKey: e.S3_SECRET_ACCESS_KEY! },
  });
  const base = (e.S3_PUBLIC_URL ?? `https://${e.S3_BUCKET}.s3.${e.S3_REGION}.amazonaws.com`).replace(/\/$/, "");
  return {
    async put(key, bytes, contentType) {
      await client.send(
        new PutObjectCommand({ Bucket: e.S3_BUCKET, Key: key, Body: bytes, ContentType: contentType }),
      );
    },
    url: (key) => `${base}/${key}`,
  };
}

let instance: Storage | undefined;

export function storage(): Storage {
  instance ??= env().STORAGE_DRIVER === "s3" ? s3Storage() : localStorage;
  return instance;
}
